sys_script_email.script:
(function runMailScript(current, template, email, email_action, event) {
    var grAtt = new GlideRecord('sys_attachment');
    grAtt.addQuery('table_name', current.getTableName());
    grAtt.addQuery('table_sys_id', current.getUniqueValue());
    grAtt.addQuery('file_name', 'CONTAINS', 'Vollmacht');
    grAtt.orderByDesc('sys_created_on');
    grAtt.setLimit(1);
    grAtt.query();

    if (grAtt.next()) {
        var sa = new GlideSysAttachment();
        sa.copy(current.getTableName(), current.getUniqueValue(), 'sys_email', email.sys_id);
    }
})(current, template, email, email_action, event);
